mapper.select:
select f.category_id as categoryId,
	c.category_name as categoryName,
	c.category_type as categoryType,
	ifnull(sum(f.amount), 0) as totalAmount,
	count(1) as recordCount
from biz_finance_record f
	left join biz_finance_category c on c.category_id = f.category_id and c.del_flag = '0'

	f.del_flag = '0'
	 AND f.record_type = #{recordType} 
	 AND f.project_id = #{projectId} 
	 AND f.user_id = #{userId} 
	 AND f.dept_id = #{deptId} 
	 AND f.record_date >= #{params.beginRecordDate} 
	 AND f.record_date <= #{params.endRecordDate} 

	${params.dataScope}

group by f.category_id, c.category_name, c.category_type
order by totalAmount desc



